from dataclasses import dataclass
from datetime import datetime
from decimal import Decimal
from typing import Optional

# PROVISIONAL policy: product has not decided. Change only here.
EXPIRED_PROMO_POLICY = "confirm"  # "confirm" | "ignore" | "reject"


@dataclass(frozen=True)
class Promotion:
    code: str
    percent_off: Decimal
    expires_at: datetime


@dataclass(frozen=True)
class CheckoutResult:
    status: str  # "ok" | "needs_confirmation" | "rejected"
    total: Decimal
    promo_applied: bool
    message: Optional[str] = None


def checkout(subtotal: Decimal, promo: Optional[Promotion], now: datetime,
             confirmed_without_promo: bool = False) -> CheckoutResult:
    if promo is None:
        return CheckoutResult("ok", subtotal, False)
    if now < promo.expires_at:
        total = (subtotal * (Decimal(100) - promo.percent_off) / 100).quantize(Decimal("0.01"))
        return CheckoutResult("ok", total, True)

    msg = f"Promotion {promo.code} has expired"
    if EXPIRED_PROMO_POLICY == "reject":
        return CheckoutResult("rejected", subtotal, False, msg)
    if EXPIRED_PROMO_POLICY == "confirm" and not confirmed_without_promo:
        return CheckoutResult("needs_confirmation", subtotal, False, msg)
    return CheckoutResult("ok", subtotal, False, msg)
