cat > test_checkout.py <<'E'
from datetime import datetime, timedelta
from decimal import Decimal as D
import checkout
from checkout import Promotion, checkout as run

NOW = datetime(2026, 11, 22)
valid = Promotion("A", D(10), NOW + timedelta(days=1))
expired = Promotion("B", D(10), NOW - timedelta(seconds=1))


def test_valid_promo_applies():
    r = run(D("100"), valid, NOW)
    assert (r.status, r.total, r.promo_applied) == ("ok", D("90.00"), True)


def test_expired_promo_needs_confirmation_at_full_price():
    r = run(D("100"), expired, NOW)
    assert (r.status, r.total, r.promo_applied) == ("needs_confirmation", D("100"), False)
    assert "expired" in r.message


def test_confirmed_expired_promo_proceeds_without_discount():
    r = run(D("100"), expired, NOW, confirmed_without_promo=True)
    assert (r.status, r.total, r.promo_applied) == ("ok", D("100"), False)


def test_expiry_instant_counts_as_expired():
    p = Promotion("C", D(10), NOW)
    assert run(D("100"), p, NOW).status == "needs_confirmation"


def test_no_promo():
    assert run(D("50"), None, NOW).total == D("50")


def test_reject_policy(monkeypatch):
    monkeypatch.setattr(checkout, "EXPIRED_PROMO_POLICY", "reject")
    assert run(D("100"), expired, NOW).status == "rejected"


def test_ignore_policy(monkeypatch):
    monkeypatch.setattr(checkout, "EXPIRED_PROMO_POLICY", "ignore")
    r = run(D("100"), expired, NOW)
    assert (r.status, r.total) == ("ok", D("100"))
